card.statement:
Define a set of elements $e_k^{(i)}\in \K_q(\bar x,\bar y)^{S_n}$ for $i\in\iv{0}{n}$, $k\in\iv{0}{n-i}$ recursively by

\begin{subequations}
\begin{align}
e_k^{(0)} =& e_k,\qquad \forall k\in\iv{0}{n}, \\
e_k^{(1)} =& t_{k+1},\qquad \forall k\in\iv{0}{n-1},\\
e_k^{(i)} =& e_{k+1}^{(i-2)}e_0^{(i-1)}e_{n-i+1}^{(i-1)}
-(-1)^{k+1} e_0^{(i-2)}  e_{n-i-k}^{(i-1)}  e_0^{(i-1)}  \\
&-(-1)^{n-i+1-k} e_{n-i+2}^{(i-2)} e_{n-i+1-k}^{(i-1)}e_{n-i+1}^{(i-1)},
\qquad\forall k\in\iv{0}{n-i}, \forall i\in\iv{2}{n}, \nonumber
\end{align}
\end{subequations}

where $e_d$ and $t_j$ were defined in <<ref:eq:ed_def>> and <<ref:eq:PX>> respectively. Let

\begin{subequations}
\begin{align}
(X_1,X_2,\ldots,X_n)= & (e_n^{(0)}, e_{n-1}^{(1)},\ldots ,e_1^{(n-1)}),\\
(Y_1,Y_2,\ldots,Y_n)= & (e_0^{(1)}, e_0^{(2)},\ldots e_0^{(n)} ),
\end{align}
\end{subequations}

and put

\begin{subequations}
\begin{gather}
\widehat{X}_1  = X_1,\quad \widehat{X}_i = Y_{i-1}^{(-1)^i} X_i^{(-1)^{i+1}},\qquad\forall i\in\iv{2}{n},\\
\widehat{Y}_1  = Y_1,\quad \widehat{Y}_2 = Y_1^{-2}Y_2,\quad\widehat{Y}_j=Y_{j-2}^{-1}Y_{j-1}^{-2}Y_j,
\qquad\forall j\in\iv{3}{n},
\end{gather}
\end{subequations}

Then there is an isomorphism of $\K$-algebras

\begin{align}
\K_q(\bar x,\bar y)\overset{\sim}{\longrightarrow} & \K_q(\bar x,\bar y)^{S_n}
\intertext{given by}
x_k\longmapsto &\widehat{X}_k,\qquad\forall k\in\iv{1}{n},\\
y_k\longmapsto &\widehat{Y}_k,\qquad\forall k\in\iv{1}{n}.
\end{align}
